def apply_fade(img, strength=0.15):
    """Apply faded/matte look by lifting blacks"""
    result = img.copy().astype(np.float32)
    lift = strength * 255
    result = result + lift
    result = np.clip(result, 0, 255)
    return result.astype(np.uint8)
