def extract_base64_bytes(data_url):
    """Helper to extract bytes from a base64 data URL."""
    try:
        if 'base64,' in data_url:
            header, encoded = data_url.split('base64,')
            return base64.b64decode(encoded)
        return None
    except Exception:
        return None
